package ch.bob.degirocompanion
/** Closed vocabulary: unknown strings never leave the device. */
internal object PhoneDiagnosticPolicy {
    private val allowed=setOf("COMPLETE","IDENTITY_CHANGED","INVALID_QUOTES","INVALID_VIEW","NAVIGATION_REJECTED","NONE","NO_QUOTES","OTHER","PARTIAL","PROTECTED_LOGIN","PROTECTED_ORDER","PROTECTED_ORDER_CONFIRM","PROTECTED_ORDER_TYPE","PROTECTED_ORDER_PRICE","PROTECTED_ORDER_QUANTITY","PROTECTED_PASSWORD","PROTECTED_SENSITIVE_CONTENT","PROTECTED_SENSITIVE_INPUT","PROTECTED_VIEW","READ_TIMEOUT","RESULT_MISSING","RETURN_FAILED","RUN_TIMEOUT","SCREEN_LOCKED","SCROLL_LAYOUT_CHANGED","SCROLL_LIMIT","SEARCH_AMBIGUOUS","SEARCH_MISSING","SEEK_LIMIT","SERVICE_INTERRUPTED","STOPPED","STORAGE_ERROR","TRANSFER_ERROR","UNRECOGNIZED_INPUT","UNSAFE_VIEW","USER_INTERRUPTED","USER_STOP")
    fun code(value:String):String=if(value in allowed)value else "OTHER"
}
